 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # A vertical 5-bar is a boundary: repeat the color pattern at its lower
    # right end upwards along the bar.
    for c in range(w):
        rs = [r for r in range(h) if g[r][c] == 5]
        if len(rs) < 2:
            continue
        top, bottom = min(rs), max(rs)
        if rs != list(range(top, bottom + 1)) or c + 1 >= w:
            continue
        # Collect the consecutive seed rows adjoining the bottom of the bar.
        seed_rows = []
        r = bottom
        while r >= top and any(g[r][j] != 0 for j in range(c + 1, w)):
            seed_rows.append([g[r][j] for j in range(c + 1, w)])
            r -= 1
        if seed_rows:
            seed_rows.reverse()
            for r in range(top, bottom + 1):
                pat = seed_rows[(r - top) % len(seed_rows)]
                for k, v in enumerate(pat, c + 1):
                    if k < w:
                        g[r][k] = v

    # A horizontal 5-bar with a color strip beneath its left end: copy each
    # strip color across the width of the bar.
    for r in range(h):
        cs = [c for c in range(w) if g[r][c] == 5]
        if len(cs) < 2:
            continue
        left, right = min(cs), max(cs)
        if cs != list(range(left, right + 1)) or r + 1 >= h:
            continue
        # Copy contiguous nonzero seed cells below the bar's left endpoint.
        rr = r + 1
        while rr < h and g[rr][left] != 0:
            color = g[rr][left]
            for c in range(left + 1, right + 1):
                if g[rr][c] == 0:
                    g[rr][c] = color
            rr += 1
    return g
